package com.example.pathfinder.ui.screen.settingsimport android.content.Contextimport android.net.Uriimport android.os.Environmentimport android.widget.Toastimport androidx.activity.compose.rememberLauncherForActivityResultimport androidx.activity.result.contract.ActivityResultContractsimport androidx.appcompat.app.AppCompatDelegateimport androidx.compose.foundation.backgroundimport androidx.compose.foundation.clickableimport androidx.compose.foundation.layout.*import androidx.compose.foundation.shape.RoundedCornerShapeimport androidx.compose.material.icons.Iconsimport androidx.compose.material.icons.filled.*import androidx.compose.material3.*import androidx.compose.runtime.*import androidx.compose.ui.Alignmentimport androidx.compose.ui.Modifierimport androidx.compose.ui.graphics.Colorimport androidx.compose.ui.platform.LocalContextimport androidx.compose.ui.text.font.FontWeightimport androidx.compose.ui.unit.dpimport androidx.compose.ui.unit.spimport androidx.navigation.NavControllerimport com.example.pathfinder.navigation.Screenimport com.example.pathfinder.utils.SettingsManagerimport java.io.Fileimport java.io.FileOutputStreamimport java.io.InputStream@OptIn(ExperimentalMaterial3Api::class)@Composablefun SettingsScreen(    navController: NavController,    onLogout: () -> Unit = {}) {    val context = LocalContext.current    var isDarkMode by remember { mutableStateOf(SettingsManager.isDarkMode(context)) }    var notificationsEnabled by remember { mutableStateOf(SettingsManager.isNotificationEnabled(context)) }    val launcher = rememberLauncherForActivityResult(        contract = ActivityResultContracts.OpenDocument(),        onResult = { uri: Uri? ->            uri?.let {                copyPdfToDownloads(context, it)            }        }    )    Scaffold(        topBar = {            TopAppBar(                title = { Text("Cài đặt", fontWeight = FontWeight.Bold) },                navigationIcon = {                    IconButton(onClick = { navController.popBackStack() }) {                        Icon(Icons.Default.ArrowBack, contentDescription = "Quay lại")                    }                }            )        }    ) { padding ->        Column(            modifier = Modifier                .padding(padding)                .fillMaxSize()                .background(MaterialTheme.colorScheme.background)                .padding(16.dp),            verticalArrangement = Arrangement.spacedBy(12.dp)        ) {            SettingsItem("Thông tin tài khoản", Icons.Default.Person) {                navController.navigate(Screen.Profile.route)            }            SettingsItem("Đổi mật khẩu", Icons.Default.Lock) {                navController.navigate(Screen.ChangePassword.route)            }            Row(                modifier = Modifier                    .fillMaxWidth()                    .background(Color.White, RoundedCornerShape(12.dp))                    .padding(16.dp),                verticalAlignment = Alignment.CenterVertically            ) {                Icon(Icons.Default.Notifications, contentDescription = null, tint = Color(0xFF5B5B5B))                Spacer(modifier = Modifier.width(16.dp))                Text(                    text = "Thông báo",                    fontSize = 16.sp,                    color = Color.Black,                    modifier = Modifier.weight(1f)                )                Switch(                    checked = notificationsEnabled,                    onCheckedChange = {                        notificationsEnabled = it                        SettingsManager.setNotificationEnabled(context, it)                    }                )            }            SettingsItem("Chính sách & Điều khoản", Icons.Default.Description) {                navController.navigate(Screen.Policy.route)            }            SettingsItem("Hỗ trợ", Icons.Default.Help) {                navController.navigate(Screen.Help.route)            }            Divider(color = Color.Gray.copy(alpha = 0.4f), thickness = 1.dp)            SettingsItem("Đăng xuất", Icons.Default.Logout) {                onLogout()            }        }    }}@Composablefun SettingsItem(label: String, icon: androidx.compose.ui.graphics.vector.ImageVector, onClick: () -> Unit) {    Surface(        modifier = Modifier            .fillMaxWidth()            .clickable { onClick() },        shape = RoundedCornerShape(12.dp),        tonalElevation = 2.dp,        shadowElevation = 1.dp    ) {        Row(            modifier = Modifier                .background(Color.White)                .padding(16.dp),            verticalAlignment = Alignment.CenterVertically        ) {            Icon(imageVector = icon, contentDescription = null, tint = Color(0xFF5B5B5B))            Spacer(modifier = Modifier.width(16.dp))            Text(text = label, fontSize = 16.sp, color = Color.Black)        }    }}fun copyPdfToDownloads(context: Context, uri: Uri) {    try {        val inputStream: InputStream? = context.contentResolver.openInputStream(uri)        val fileName = "CV_Tu_Thiet_Bi.pdf"        val downloadsDir = Environment.getExternalStoragePublicDirectory(Environment.DIRECTORY_DOWNLOADS)        val outputFile = File(downloadsDir, fileName)        val outputStream = FileOutputStream(outputFile)        inputStream?.copyTo(outputStream)        inputStream?.close()        outputStream.close()        Toast.makeText(context, "Đã lưu về thư mục Downloads", Toast.LENGTH_SHORT).show()    } catch (e: Exception) {        e.printStackTrace()        Toast.makeText(context, "Lỗi khi tải CV", Toast.LENGTH_SHORT).show()    }}